/* ========================================================================== */
/* Matrix selection helpers                                                    */
/* ========================================================================== */

const float *oaci_semac_get_from_shd_matrix(int order)
{
   switch (order) {
   case 1: return oaci_spfb_from_shd_foa;
   case 2: return oaci_spfb_from_shd_soa;
   case 3: return oaci_spfb_from_shd_toa;
   case 4: return oaci_spfb_from_shd_fourthoa;
   case 5: return oaci_spfb_from_shd_fifthoa;
   default: return NULL;
   }
}

const float *oaci_semac_get_to_shd_matrix(int order)
{
   switch (order) {
   case 1: return oaci_spfb_to_shd_foa;
   case 2: return oaci_spfb_to_shd_soa;
   case 3: return oaci_spfb_to_shd_toa;
   case 4: return oaci_spfb_to_shd_fourthoa;
   case 5: return oaci_spfb_to_shd_fifthoa;
   default: return NULL;
   }
}

/* ========================================================================== */
/* SPFB matrix application                                                    */
/* ========================================================================== */

/* Apply a square projection matrix: out[i] = sum_j proj[i*channels+j]*in[j].
   The same matmul serves both directions; the chosen matrix (from_shd or
   to_shd) determines what the projection does. */
void oaci_semac_project(const float *proj,
   const celt_sig *freq_in, celt_sig *freq_out,
   int channels, int num_bins)
{
   int i, j, k;
   for (i = 0; i < channels; i++) {
      for (k = 0; k < num_bins; k++) {
         float sum = 0;
         for (j = 0; j < channels; j++)
            sum += proj[i * channels + j] * freq_in[j * num_bins + k];
         freq_out[i * num_bins + k] = sum;
      }
   }
}

/* ========================================================================== */
/* Beam-projection downmix / upmix                                            */
/* Reduce the beam count by routing through SHD: beams -> ambisonics (demix)  */
/* -> SH order truncation -> lower-order beams (mix). Identity at full order.  */
/* ========================================================================== */

/* Downmix num_beams input-order beams to coding_channels transport beams.
   Only used by the normalized encoder path; the non-normalized path extracts
   transport beams directly from the input ambisonics. */
#ifdef SEMAC_SPATIAL_NORMALIZATION
static void oaci_semac_downmix_beams(const celt_sig *beams_in, celt_sig *beams_out,
   int order_in, int order_out, int num_bins)
{
   int num_beams = oaci_semac_get_channels(order_in);
   int coding_channels = oaci_semac_get_channels(order_out);
   const float *proj_to_shd = oaci_semac_get_to_shd_matrix(order_in);
   const float *proj_from_shd = oaci_semac_get_from_shd_matrix(order_out);
   VARDECL(celt_sig, ambi);
   SAVE_STACK;

   /* order_in == order_out: to_shd then from_shd is the identity -> just copy, no round-trip. */
   if (order_in == order_out) {
      OAC_COPY(beams_out, beams_in, num_beams * num_bins);
      RESTORE_STACK;
      return;
   }

   celt_assert(proj_to_shd != NULL && proj_from_shd != NULL);

   ALLOC(ambi, num_beams * num_bins, celt_sig);
   oaci_semac_project(proj_to_shd, beams_in, ambi, num_beams, num_bins);
   /* projecting only coding_channels SHD inputs back to beams = SH order truncation */
   oaci_semac_project(proj_from_shd, ambi, beams_out, coding_channels, num_bins);

   RESTORE_STACK;
}
#endif /* SEMAC_SPATIAL_NORMALIZATION */

/* Upmix coding_channels transport beams back to num_beams beams (inverse). */
static void oaci_semac_upmix_beams(const celt_sig *beams_in, celt_sig *beams_out,
   int order_in, int order_out, int num_bins)
{
   int c;
   int num_beams = oaci_semac_get_channels(order_out);
   int coding_channels = oaci_semac_get_channels(order_in);
   const float *proj_to_shd = oaci_semac_get_to_shd_matrix(order_in);
   const float *proj_from_shd = oaci_semac_get_from_shd_matrix(order_out);
   VARDECL(celt_sig, ambi);
   SAVE_STACK;

   /* order_in == order_out: to_shd then from_shd is the identity -> just copy, no round-trip. */
   if (order_in == order_out) {
      OAC_COPY(beams_out, beams_in, num_beams * num_bins);
      RESTORE_STACK;
      return;
   }

   celt_assert(proj_to_shd != NULL && proj_from_shd != NULL);

   ALLOC(ambi, num_beams * num_bins, celt_sig);
   oaci_semac_project(proj_to_shd, beams_in, ambi, coding_channels, num_bins);
   for (c = coding_channels; c < num_beams; c++)
      OAC_CLEAR(ambi + c * num_bins, num_bins);
   oaci_semac_project(proj_from_shd, ambi, beams_out, num_beams, num_bins);

   RESTORE_STACK;
}

/* ========================================================================== */
/* Spatial energy extraction (encoder side)                                   */
/* ========================================================================== */

void oaci_semac_compute_spatial_energy(const CELTMode *mode,
   const celt_sig *shdFreq, celt_sig *beamFreq,
   celt_ener *spatialBandE, celt_glog *spatialLogE,
   int input_order, int effEnd, int end, int C, int LM, int arch)
{
   int num_beams = oaci_semac_get_channels(input_order);
   int N = mode->shortMdctSize << LM;
   const float *proj_from_shd = oaci_semac_get_from_shd_matrix(input_order);

   celt_assert(proj_from_shd != NULL);

   /* Transform ambisonics -> beams and extract per-beam band energies. */
   oaci_semac_project(proj_from_shd, shdFreq, beamFreq, C, N);
   oaci_compute_band_energies(mode, beamFreq, spatialBandE, effEnd, num_beams, LM, arch);
   oaci_amp2Log2(mode, effEnd, end, spatialBandE, spatialLogE, num_beams);
}


void oaci_semac_create_transport_channels(const CELTMode *mode,
   const celt_sig *shdFreq, const celt_sig *beamFreq, celt_sig *outFreq,
   const celt_ener *spatialBandE,
   int input_order, int effEnd, int coding_channels,
   int transport_domain, int LM)
{
   int num_beams = oaci_semac_get_channels(input_order);
   int N = mode->shortMdctSize << LM;
   int c;
#ifdef SEMAC_SPATIAL_NORMALIZATION
   /* Whiten the input beams to unit per-band energy, then form the transport (from beamFreq;
      shdFreq unused in this path). */
   int M = 1 << LM;
   VARDECL(celt_norm, beamNorm);
   SAVE_STACK;
   (void)shdFreq;
   ALLOC(beamNorm, num_beams * N, celt_norm);
   oaci_normalise_bands(mode, beamFreq, beamNorm, spatialBandE, effEnd, num_beams, M);
   if (transport_domain == SEMAC_DOMAIN_BEAM) {
      /* Downmix the normalized beams to the transport beams (identity at full order). */
      oaci_semac_downmix_beams((const celt_sig *)beamNorm, outFreq,
         input_order, oaci_semac_get_order(coding_channels), N);
   } else if (transport_domain == SEMAC_DOMAIN_SHD) {
      /* Project the normalized beams back to ambisonics. */
      const float *proj_to_shd = oaci_semac_get_to_shd_matrix(input_order);
      celt_assert(proj_to_shd != NULL);
      oaci_semac_project(proj_to_shd, (const celt_sig *)beamNorm, outFreq, num_beams, N);
   } else {
      celt_assert(0); /* unknown transport domain */
   }
   RESTORE_STACK;
#else /* !SEMAC_SPATIAL_NORMALIZATION */
   (void)spatialBandE; (void)beamFreq; (void)effEnd;
   if (transport_domain == SEMAC_DOMAIN_BEAM) {
      /* Downmix from the input ambisonics at natural level. Full transport: envelope skipped.
         Reduced: decoder restores the envelope. */
      const float *proj_from_shd =
         oaci_semac_get_from_shd_matrix(oaci_semac_get_order(coding_channels));
      VARDECL(celt_sig, tmp);
      SAVE_STACK;
      celt_assert(proj_from_shd != NULL);
      ALLOC(tmp, coding_channels * N, celt_sig);   /* projection can't be in-place (outFreq aliases shdFreq) */
      oaci_semac_project(proj_from_shd, shdFreq, tmp, coding_channels, N);
      OAC_COPY(outFreq, tmp, coding_channels * N);
      RESTORE_STACK;
   } else if (transport_domain == SEMAC_DOMAIN_SHD) {
      /* SHD transport = the input ambisonics (first coding_channels SH), natural level. */
      if (outFreq != shdFreq)
         OAC_COPY(outFreq, shdFreq, coding_channels * N);
   } else {
      celt_assert(0); /* unknown transport domain */
   }
#endif /* SEMAC_SPATIAL_NORMALIZATION */
   /* Zero the untransmitted channels (only the first coding_channels are coded). */
   for (c = coding_channels; c < num_beams; c++)
      OAC_CLEAR(outFreq + c * N, N);
}

/* ========================================================================== */
/* SEMAC reconstruction (decoder side)                                        */
/* ========================================================================== */

void oaci_semac_reconstruct(const CELTMode *mode,
   celt_norm *X, celt_glog *oldBandE,
   celt_glog *outLogE,
   const celt_glog *spatialLogE,
   int coding_channels, int output_channels,
   int input_order, int transport_domain,
   int start, int effEnd, int end,
   int LM, int arch)
{
   int i, b, c, k, band_start, band_end;
   int num_beams = oaci_semac_get_channels(input_order);
   int nbEBands = mode->nbEBands;
   int M = 1 << LM;
   int N = mode->shortMdctSize << LM;
   const oac_int16 *eBands = mode->eBands;
   const float *proj_from_shd = oaci_semac_get_from_shd_matrix(input_order);
   const float *proj_to_shd = oaci_semac_get_to_shd_matrix(input_order);

   VARDECL(celt_sig, freq);
   VARDECL(celt_sig, beamFreq);
   VARDECL(celt_sig, outFreq);
   VARDECL(celt_ener, outBandE);
   SAVE_STACK;

   celt_assert(proj_from_shd != NULL && proj_to_shd != NULL);
   celt_assert(output_channels == num_beams);

   ALLOC(freq, output_channels * N, celt_sig);
   ALLOC(beamFreq, num_beams * N, celt_sig);
   ALLOC(outFreq, output_channels * N, celt_sig);
   ALLOC(outBandE, output_channels * nbEBands, celt_ener);

   /* Step 1: Denormalize coded channels to get full MDCT spectrum */
   for (c = 0; c < coding_channels; c++)
      oaci_denormalise_bands(mode, X + c * N, freq + c * N,
         oldBandE + c * nbEBands, start, effEnd, M, 1, 0);

   /* Zero-pad higher-order channels */
   for (c = coding_channels; c < output_channels; c++)
      OAC_CLEAR(freq + c * N, N);

   /* Step 2: Get beam-domain signals from the coded transport channels. */
   if (transport_domain == SEMAC_DOMAIN_BEAM) {
      /* Beam-projection: upmix the coding_channels coded transport beams back
         to num_beams input-order beams (collapses to a plain copy at full
         order). freq holds the denormalized transport beams in its first
         coding_channels channels from Step 1. */
      oaci_semac_upmix_beams(freq, beamFreq,
         oaci_semac_get_order(coding_channels), input_order, N);
   } else if (transport_domain == SEMAC_DOMAIN_SHD) {
      /* SHD: project from SHD, ambisonics -> beams. */
      oaci_semac_project(proj_from_shd, freq, beamFreq, output_channels, N);
   } else {
      celt_assert(0); /* unknown transport domain */
   }

   /* Step 3: per-beam correction to the transmitted envelope, then inverse SPFB */
   for (i = start; i < effEnd; i++) {
      band_start = M * eBands[i];
      band_end = M * eBands[i + 1];

      for (b = 0; b < num_beams; b++) {
         float sum = 1e-27f;
         float beamA, spatialGain, correctionGain;
         for (k = band_start; k < band_end; k++)
            sum += beamFreq[b * N + k] * beamFreq[b * N + k];
         beamA = (float)sqrt(sum);

         /* Scale by spatialGain/beamA: re-impose the envelope. lg = bandLogE + eMeans, as denormalise_bands. */
#ifdef FIXED_POINT
         {
            celt_glog lg = ADD32(spatialLogE[i + b * nbEBands],
               SHL32((oac_val32)oaci_eMeans[i], DB_SHIFT - 4));
            spatialGain = (float)celt_exp2_db(lg);
         }
#else
         {
            celt_glog lg = spatialLogE[i + b * nbEBands] + oaci_eMeans[i];
            spatialGain = celt_exp2_db(MIN32(32.f, lg));
         }
#endif
         correctionGain = spatialGain / (1e-27f + beamA);
         /* No envelope available (beam full-transport): re-imposition is identity. */
         if (oaci_semac_envelope_absent(transport_domain, coding_channels, num_beams))
            correctionGain = 1.f;
         for (k = band_start; k < band_end; k++)
            beamFreq[b * N + k] *= correctionGain;
      }

      /* Inverse SPFB for this band */
      for (c = 0; c < output_channels; c++) {
         for (k = band_start; k < band_end; k++) {
            float sum = 0;
            for (b = 0; b < num_beams; b++)
               sum += proj_to_shd[c * output_channels + b] * beamFreq[b * N + k];
            outFreq[c * N + k] = sum;
         }
      }
   }

   /* Zero out bands outside [start, effEnd) */
   for (c = 0; c < output_channels; c++) {
      for (k = 0; k < M * eBands[start]; k++)
         outFreq[c * N + k] = 0;
      for (k = M * eBands[effEnd]; k < N; k++)
         outFreq[c * N + k] = 0;
   }

   /* Step 4: Compute output band energies and re-normalize for synthesis */
   oaci_compute_band_energies(mode, outFreq, outBandE, effEnd, output_channels, LM, arch);
   oaci_normalise_bands(mode, outFreq, X, outBandE, effEnd, output_channels, M);

   /* Output (full-order) band log-energies for synthesis go to outLogE. oldBandE is left as the
      DECODED TRANSPORT energy (the value just denormalized in Step 1), matching the encoder's
      persistent state, so the next frame's transport coarse-energy prediction and the
      energy-weighted bit allocation use the same transport energy on both sides. */
   oaci_amp2Log2(mode, effEnd, end, outBandE, outLogE, output_channels);

   RESTORE_STACK;
}

/* Turn one band's per-channel log2 amplitudes into signed per-dim BITRES offsets in Q6:
   offset_c = lambda * (log2amp_c - per-band mean) scaled to bands.c units ((1<<BITRES) x Q6).
   The mean is the conservation pivot, so offsets sum to ~0 across channels; SEMAC_ALLOC_LAMBDA
   scales the steering strength (1.0 full, 0.0 equal). bands.c applies
   (band_N-1)*offset + floor + renorm and shifts the Q6 out. */
static void semac_write_band_offsets(const float *log2amp, int C, int nbEBands, int i,
   oac_int32 *offsets_q6) {
   int c;
   float mean = 0.f;
   for (c = 0; c < C; c++) mean += log2amp[c];
   mean /= C;
   for (c = 0; c < C; c++) {
      float off = SEMAC_ALLOC_LAMBDA * (log2amp[c] - mean) * (float)((1 << BITRES) * 64);
      offsets_q6[c*nbEBands + i] = (oac_int32)(off >= 0.f ? off + 0.5f : off - 0.5f);
   }
}

/* Per-(channel,band) bit-allocation offsets for SEMAC_ENERGY_ALLOC, derived directly from the
   coded transport band energies oldBandE (the actual per-channel amplitudes). eMeans is per-band
   (constant across channels), so it cancels in the per-band mean and oldBandE serves directly as
   log2-amplitude. Both encoder and decoder hold the same oldBandE (coarse+fine), so no side-info.
   Offset = log2(amp_c) - per-band mean(log2 amp): +1 bit/dim per amplitude doubling above the mean.
   This is the default weight source. Layout offsets_q6[c*nbEBands + i]. */
void oaci_semac_compute_bit_weights_from_tc(const celt_glog *oldBandE, int C, int nbEBands,
   int start, int end, oac_int32 *offsets_q6) {
   int c, i, k;
   for (k = 0; k < C * nbEBands; k++) offsets_q6[k] = 0;
   if (C <= 0 || C > SEMAC_MAX_BEAMS) return;
   celt_assert(nbEBands <= SEMAC_MAX_BANDS);
   for (i = start; i < end; i++) {
      float log2amp[SEMAC_MAX_BEAMS];
      for (c = 0; c < C; c++) log2amp[c] = (float)oldBandE[c*nbEBands + i];
      semac_write_band_offsets(log2amp, C, nbEBands, i, offsets_q6);
   }
}

